INSERT INTO `v1_6e21a5fc9bb49f65e7cadc8f2fad1592a2fdda75063f06633b7d4a57e7a55201` VALUES ("イベントボスには非常に高い「Total HP」が設定されております。\n「Total HP」は、皆さまがバトル中に与えたダメージの分だけ減らせる\nのだとか。豪華報酬を目指し、力を合わせて討伐いたしましょう。", 1, 1, 1012, 2);
INSERT INTO `v1_6e21a5fc9bb49f65e7cadc8f2fad1592a2fdda75063f06633b7d4a57e7a55201` VALUES ("ボスバトルは、イベント期間中に配布される「討伐チケット」を消費して\n挑戦できます。また、難易度は「ボス詳細」から変更できますよ。\n討伐を達成した難易度はスキップも行えるので、活用してくださいまし。", 1, 1, 1013, 3);
INSERT INTO `v1_6e21a5fc9bb49f65e7cadc8f2fad1592a2fdda75063f06633b7d4a57e7a55201` VALUES ("報酬交換では「討伐報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 2, 1, 1021, 4);
